CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), github_id text UNIQUE NOT NULL, email text UNIQUE NOT NULL, name text, image text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mcp_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, slug text UNIQUE NOT NULL, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wallet_bindings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, address text UNIQUE NOT NULL, verified_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wallet_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, nonce text UNIQUE NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS published_pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, slug text NOT NULL, title text NOT NULL, content text NOT NULL, blob_url text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS oauth_token_uses (kind text NOT NULL, jti text NOT NULL, used_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind, jti));
